package com.classvoice.controller;
import com.classvoice.dao.UserDAO; import com.classvoice.model.User; import com.classvoice.util.PasswordUtil; import com.classvoice.util.WebUtil; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/login") public class LoginServlet extends HttpServlet { protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{String email=WebUtil.trim(r.getParameter("email")).toLowerCase(),pass=r.getParameter("password");if(email.isBlank()||pass==null||pass.isBlank()){r.setAttribute("error","Email and password are required.");r.getRequestDispatcher("/login.jsp").forward(r,p);return;}try{User u=new UserDAO().findByEmail(email);if(u==null||!PasswordUtil.matches(pass,u.getPassword())){r.setAttribute("error","Invalid email or password.");r.getRequestDispatcher("/login.jsp").forward(r,p);return;}HttpSession old=r.getSession(false);if(old!=null)old.invalidate();HttpSession s=r.getSession(true);s.setMaxInactiveInterval(30*60);s.setAttribute("user",u);p.sendRedirect(r.getContextPath()+("teacher".equals(u.getRole())?"/teacher/dashboard":"/student/dashboard"));}catch(Exception e){throw new ServletException(e);}} }
